function arrow(g, x1, y1, x2, y2, color, w, hs) {
  var ang = Math.atan2(y2 - y1, x2 - x1), h = hs || 13;
  g.line(x1, y1, x2 - Math.cos(ang) * h * 0.85, y2 - Math.sin(ang) * h * 0.85)
    .stroke({ color: color, width: w, linecap: 'butt' });
  var px = Math.cos(ang + Math.PI / 2), py = Math.sin(ang + Math.PI / 2);
  var p = [[x2, y2],
  [x2 - Math.cos(ang) * h + px * h * 0.42, y2 - Math.sin(ang) * h + py * h * 0.42],
  [x2 - Math.cos(ang) * h - px * h * 0.42, y2 - Math.sin(ang) * h - py * h * 0.42]];
  g.polygon(p.map(function (a) { return a[0] + ',' + a[1]; }).join(' ')).fill(color);
}
