var bulbD = 'M504,304 L504,266 Q504,246 531,246 Q558,246 558,266 L558,304 Z';
Ltube.path(bulbD).fill('#fff').stroke({ color: C.ink, width: 3, linejoin: 'round' });
var naLevel = 292;
var naLiquid = Ltube.rect(50, 304 - naLevel).move(506, naLevel).fill(C.pink);
var naLine = Ltube.line(506, naLevel, 556, naLevel).stroke({ color: C.pinkDark, width: 2.5 });
Ltube.path(bulbD).fill('none').stroke({ color: C.ink, width: 3, linejoin: 'round' });
var flaskHit = Ltube.rect(56, 60).move(503, 245).fill('#fff').opacity(0);
hover(flaskHit, 'Liquid Na metal reservoir', 'Liquid sodium',
  'Molten sodium (density ≈ 0.93 g/cm³) floats on the denser salt bath (≈ 1.6 g/cm³). It rises into this side reservoir and is drawn off continuously through the Na outlet.');

/* ---------- voltage source and wiring ---------- */
var wireCath = 'M512,432 H536 V534 H600';
var wireAn = 'M326,552 H600';
Ltube.path(wireCath).fill('none').stroke({ color: C.ink, width: 5, linejoin: 'round' });
Ltube.path(wireAn).fill('none').stroke({ color: C.ink, width: 5 });
var eCath = Ltube.path(wireCath).fill('none').stroke({ color: '#ffd24d', width: 3, dasharray: '7,11', linejoin: 'round' }).opacity(0);
var eAn = Ltube.path(wireAn).fill('none').stroke({ color: '#ffd24d', width: 3, dasharray: '7,11' }).opacity(0);
var vbox = Ltube.rect(96, 58).move(598, 512).fill('#9a9a9a').stroke({ color: C.ink, width: 2.5 });
txt(Ltube, 'Voltage', 610, 520, 15, '#fff');
txt(Ltube, 'source', 610, 540, 15, '#fff');
hover(vbox, 'Voltage source — pushes electrons out of the anode into the cathode', 'The driving force',
  'Electrolysis is not spontaneous: the external supply pulls electrons from the anode (forcing oxidation of Cl⁻) and pushes them into the cathode (forcing reduction of Na⁺).');

/* ---------- labels ---------- */
halo(txt(Llab, 'Molten', 24, 264, 15));
halo(txt(Llab, 'NaCl', 24, 282, 15));
leader(Llab, 96, 290, 190, 290);
halo(txt(Llab, 'Iron', 48, 346, 15));
halo(txt(Llab, 'screen', 48, 364, 15));
leader(Llab, 116, 372, 246, 372);
halo(txt(Llab, 'Cathode (−)', 194, 508, 15));
leader(Llab, 246, 506, 222, 456);
halo(txt(Llab, 'Anode (+)', 340, 508, 15));
leader(Llab, 372, 506, 350, 388);
halo(txt(Llab, 'Cl₂ outlet', 500, 40, 15));
arrow(Llab, 497, 88, 596, 88, C.ink, 3, 14);
halo(txt(Llab, 'Inlet for', 634, 174, 15));
halo(txt(Llab, 'NaCl', 634, 192, 15));
leader(Llab, 448, 186, 628, 186);
halo(txt(Llab, 'Liquid', 568, 278, 15));
halo(txt(Llab, 'Na metal', 568, 296, 15));
halo(txt(Llab, 'Na outlet', 586, 372, 15));
arrow(Llab, 582, 406, 688, 406, C.ink, 3, 14);

/* ---------- overlay callout ---------- */
var callout = Lover.group().opacity(0);
function showCallout(lines, color) {
  callout.clear();
  var h = 20 + lines.length * 21;
  callout.rect(268, h).move(20, 30).radius(8).fill('#fffdf3').stroke({ color: color, width: 2.5 }).opacity(0.97);
  lines.forEach(function (ln, i) {
    callout.text(ln.t).font({ family: 'sans-serif', size: ln.s || 13.5, weight: ln.b ? 'bold' : 'normal' })
      .fill(ln.c || '#222').move(32, 38 + i * 21);
  });
  callout.opacity(1);
}
function refreshOverlay() {
  if (state.focus === 'anode') {
    showCallout([
      { t: 'ANODE (+) — oxidation', b: true, c: '#b45c12' },
      { t: '2Cl⁻(l) → Cl₂(g) + 2e⁻', c: '#2c7a1f' },
      { t: 'Overall: 2NaCl(l) → 2Na(l) + Cl₂(g)', s: 12, c: '#555' }
    ], C.orangeHi);
  } else if (state.focus === 'cathode') {
    showCallout([
      { t: 'CATHODE (−) — reduction', b: true, c: '#1d4f9e' },
      { t: '2Na⁺(l) + 2e⁻ → 2Na(l)', c: '#8e3f9b' },
      { t: 'Overall: 2NaCl(l) → 2Na(l) + Cl₂(g)', s: 12, c: '#555' }
    ], C.cathHi);
  } else if (!state.screen) {
    showCallout([
      { t: 'SCREEN REMOVED', b: true, c: '#c00000' },
      { t: '2Na(l) + Cl₂(g) → 2NaCl(l)', c: '#c00000' },
      { t: 'Products recombine — nothing is collected.', s: 12, c: '#555' }
    ], '#c00000');
  } else {
    callout.opacity(0);
  }
}

/* ---------- particle machinery ---------- */
function mkPath(pts) {
  var segs = [], tot = 0;
  for (var i = 1; i < pts.length; i++) {
    var dx = pts[i][0] - pts[i - 1][0], dy = pts[i][1] - pts[i - 1][1];
    var d = Math.sqrt(dx * dx + dy * dy); segs.push(d); tot += d;
  }
  return { pts: pts, segs: segs, total: tot || 1 };
}
function ptAt(p, s) {
  if (s <= 0) return [p.pts[0][0], p.pts[0][1]];
  var acc = 0;
  for (var i = 0; i < p.segs.length; i++) {
    if (acc + p.segs[i] >= s) {
      var f = (s - acc) / p.segs[i], a = p.pts[i], b = p.pts[i + 1];
      return [a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f];
    }
    acc += p.segs[i];
  }
  var e = p.pts[p.pts.length - 1]; return [e[0], e[1]];
}

var ions = [], bubbles = [], drops = [];

function ionStart(kind) {
  if (kind === 'cl') {
    var left = Math.random() < 0.5;
    return [left ? 190 + Math.random() * 105 : 358 + Math.random() * 108, 286 + Math.random() * 168];
  }
  return [298 + Math.random() * 56, 336 + Math.random() * 110];
}
function ionPath(io) {
  if (io.kind === 'cl') {
    var tx = io.x < 326 ? 294 : 358;
    return mkPath([[io.x, io.y], [tx + (Math.random() * 8 - 4), 366 + Math.random() * 14]]);
  }
  var right = io.x >= 326;
  return mkPath([[io.x, io.y], [right ? 429 : 220, 392 + Math.random() * 44]]);
}
function newIon(kind) {
  var el = Lpart.circle(11).fill(kind === 'cl' ? C.cl : C.na).stroke({ color: '#fff', width: 1 }).opacity(0.95);
  var st = ionStart(kind), a = Math.random() * 6.283;
  var io = { kind: kind, el: el, x: st[0], y: st[1], vx: Math.cos(a) * 18, vy: Math.sin(a) * 18, path: null, s: 0, speed: 30 };
  el.center(io.x, io.y);
  el.css('cursor', 'default');
  el.on('mousemove', function (e) {
    showTooltip(kind === 'cl' ? 'Cl⁻ chloride ion — migrates inward to the anode (+)'
      : 'Na⁺ sodium ion — migrates outward to the cathode (−)', e);
  }).on('mouseleave', hideTooltip);
  ions.push(io);
}
for (var i = 0; i < 8; i++) { newIon('cl'); newIon('na'); }

function flashAt(x, y) {
  var c = Lpart.circle(10).center(x, y).fill('#ffd24d').opacity(0.9);
  c.animate(650).attr({ r: 22, opacity: 0 });
  setTimeout(function () { c.remove(); }, 700);
}
function spawnBubble() {
  if (bubbles.length > 26) return;
  var sx = 300 + Math.random() * 52, sy = 360;
  var escape = !state.screen && Math.random() < 0.55, path, kind;
  if (escape) {
    var dir = Math.random() < 0.5 ? -1 : 1;
    path = mkPath([[sx, sy], [sx + dir * 45, 346], [326 + dir * (95 + Math.random() * 25), 331]]);
    kind = 'escape';
  } else {
    path = mkPath([[sx, sy], [315 + (Math.random() * 12 - 6), 300], [315, 262], [315, 112], [328, 88], [486, 88]]);
    kind = 'up';
  }
  var el = Lpart.circle(8).fill(C.bubble).stroke({ color: '#9aa863', width: 0.8 }).opacity(0.95).center(sx, sy);
  el.on('mousemove', function (e) { showTooltip('Cl₂ gas bubble', e); }).on('mouseleave', hideTooltip);
  bubbles.push({ el: el, path: path, s: 0, speed: 55 + Math.random() * 30, kind: kind });
}
function spawnDrop(right) {
  if (drops.length > 16) return;
  var path = right
    ? mkPath([[429, 404], [429, 336], [438, 330], [446, 297], [520, 297], [532, 308]])
    : mkPath([[220, 404], [220, 336], [412, 330], [442, 297], [520, 297], [532, 308]]);
  var el = Lpart.circle(9).fill(C.pinkDark).stroke({ color: '#c98fb4', width: 0.8 }).center(220, 404);
  el.on('mousemove', function (e) { showTooltip('Liquid Na — floats on the melt, flows to the reservoir', e); }).on('mouseleave', hideTooltip);
  drops.push({ el: el, path: path, s: 0, speed: 70 + Math.random() * 30, kind: 'drop' });
}
function spawnSpout() {
  var path = mkPath([[533, 320], [533, 388], [552, 404], [676, 406]]);
  var el = Lpart.circle(9).fill(C.pinkDark).opacity(0.9).center(533, 320);
  drops.push({ el: el, path: path, s: 0, speed: 110, kind: 'spout' });
}
function setLevel(v) {
  naLevel = Math.max(268, Math.min(296, v));
  naLiquid.attr({ y: naLevel, height: 304 - naLevel });
  naLine.plot(506, naLevel, 556, naLevel);
}

function advance(list, dt) {
  for (var i = list.length - 1; i >= 0; i--) {
    var b = list[i];
    b.s += b.speed * dt;
    var p = ptAt(b.path, b.s);
    b.el.center(p[0], p[1]);
    if (b.s >= b.path.total) {
      if (b.kind === 'escape') { flashAt(p[0], p[1]); setLevel(naLevel + 2.2); }
      if (b.kind === 'drop') {
        if (naLevel <= 270) spawnSpout(); else setLevel(naLevel - 1.6);
      }
      b.el.remove(); list.splice(i, 1);
    }
  }
}

var last = 0, wireT = 0;
function frame(ts) {
  var dt = last ? Math.min(0.05, (ts - last) / 1000) : 0;
  last = ts;
  /* ions */
  for (var i = 0; i < ions.length; i++) {
    var io = ions[i];
    if (state.running) {
      if (!io.path) { io.path = ionPath(io); io.s = 0; io.speed = 28 + Math.random() * 24; }
      io.s += io.speed * dt;
      var p = ptAt(io.path, io.s); io.x = p[0]; io.y = p[1];
      if (io.s >= io.path.total) {
        if (io.kind === 'cl') spawnBubble(); else spawnDrop(io.x > 326);
        var st = ionStart(io.kind); io.x = st[0]; io.y = st[1]; io.path = null;
      }
    } else {
      io.x += io.vx * dt; io.y += io.vy * dt;
      if (io.x < 188 || io.x > 470) { io.vx *= -1; io.x = Math.max(188, Math.min(470, io.x)); }
      if (io.y < 282 || io.y > 458) { io.vy *= -1; io.y = Math.max(282, Math.min(458, io.y)); }
      if (Math.random() < 0.02) { var a = Math.random() * 6.283; io.vx = Math.cos(a) * 18; io.vy = Math.sin(a) * 18; }
    }
    io.el.center(io.x, io.y);
  }
  advance(bubbles, dt);
  advance(drops, dt);
  if (state.running) {
    wireT -= dt * 60;
    eAn.attr('stroke-dashoffset', wireT);
    eCath.attr('stroke-dashoffset', wireT);
  }
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

/* ---------- interaction handlers ---------- */
function toggle_electrolysisRun(on) {
  state.running = !!on;
  var cb = document.getElementById('electrolysisRunInput');
  if (cb) cb.checked = state.running;
  eAn.opacity(state.running ? 1 : 0);
  eCath.opacity(state.running ? 1 : 0);
  for (var i = 0; i < ions.length; i++) {
    ions[i].path = null; ions[i].s = 0;
    var a = Math.random() * 6.283;
    ions[i].vx = Math.cos(a) * 18; ions[i].vy = Math.sin(a) * 18;
  }
  if (!state.running) {
    for (var b = bubbles.length - 1; b >= 0; b--) { bubbles[b].el.remove(); }
    bubbles.length = 0;
    for (var d = drops.length - 1; d >= 0; d--) { drops[d].el.remove(); }
    drops.length = 0;
    setLevel(292);
  }
}
function toggle_screenToggle(on) {
  state.screen = !!on;
  var cb = document.getElementById('screenToggleInput');
  if (cb) cb.checked = state.screen;
  mesh.animate(250).opacity(state.screen ? 1 : 0);
  meshHit.opacity(0);
  refreshOverlay();
}
function focusElectrode(kind) {
  state.focus = kind || null;
  anHalo.animate(180).opacity(kind === 'anode' ? 1 : 0);
  cathHalo.animate(180).opacity(kind === 'cathode' ? 1 : 0);
  refreshOverlay();
}

/* ---------- demo steps ---------- */
var steps = [
  {
    title: 'The cell at rest',
    narr: 'A steel vessel holds molten NaCl above 800 °C. A central graphite anode sits inside a cylindrical iron screen; the ring-shaped cathode surrounds it. No current flows yet, so the Na⁺ and Cl⁻ ions drift randomly.',
    st: { run: false, screen: true, focus: null }
  },
  {
    title: 'Switch on the voltage source',
    narr: 'With the external supply connected, ions stop drifting and start migrating: green Cl⁻ moves inward to the positive anode, purple Na⁺ moves outward to the negative cathode.',
    st: { run: true, screen: true, focus: null }
  },
  {
    title: 'Oxidation at the anode',
    narr: 'Each pair of chloride ions gives up electrons: 2Cl⁻(l) → Cl₂(g) + 2e⁻. Bubbles collect in the hood and rise through the green tube to the Cl₂ outlet.',
    st: { run: true, screen: true, focus: 'anode' }
  },
  {
    title: 'Reduction at the cathode',
    narr: 'At the outer cathode bars: Na⁺(l) + e⁻ → Na(l). Molten sodium is less dense than the salt bath, so it floats to the top, fills the side reservoir and drains out the Na outlet.',
    st: { run: true, screen: true, focus: 'cathode' }
  },
  {
    title: 'Why the iron screen matters',
    narr: 'Remove the screen and rising sodium meets the chlorine bubbles — the products recombine into NaCl (and dangerously so). The screen keeps the two half-cell products apart, which is what makes the process continuous and useful.',
    st: { run: true, screen: false, focus: null }
  }
];
function setStep(i) {
  state.step = (i % steps.length + steps.length) % steps.length;
  var s = steps[state.step];
  document.getElementById('demoNarration').innerHTML = '<b>' + s.title + '</b><br>' + s.narr;
  document.getElementById('stepLabel').textContent = 'Step ' + (state.step + 1) + ' / ' + steps.length;
  toggle_electrolysisRun(s.st.run);
  toggle_screenToggle(s.st.screen);
  focusElectrode(s.st.focus);
}
function nextStep() { setStep(state.step + 1); }
function prevStep() { setStep(state.step - 1); }

setStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: In a Downs cell, electrolysis of molten NaCl drives Cl⁻ to the central anode (oxidation to Cl₂ gas) and Na⁺ to the surrounding cathode (reduction to liquid Na), with an iron screen keeping the two products from recombining so each can be collected separately.
KEY INSIGHT (what students should walk away understanding): Electrolysis only pays off industrially if the two products are kept apart — the Downs cell's geometry (central anode, surrounding cathode, iron screen, buoyant liquid Na, rising Cl₂ gas) is engineered entirely around separating sodium from chlorine the instant they form.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
