/* ---------- resting Cl2 bubble plume (default, faithful to source) ---------- */
var plumePts = [[316, 268, 4], [307, 281, 3.6], [327, 285, 4.2], [314, 296, 4.4], [331, 300, 3.8],
[301, 307, 4.2], [320, 312, 4.6], [337, 315, 3.8], [296, 321, 4], [311, 326, 4.4],
