Ltube.line(400, 176, 432, 176).stroke({ color: C.ink, width: 2 });
var inletBox = Ltube.rect(62, 16).move(384, 200).fill('#fff').stroke({ color: C.ink, width: 2.5 });
hover(inletBox, 'Inlet — fresh NaCl is fed in continuously', 'Continuous feed',
  'Because sodium and chlorine are withdrawn separately and continuously, fresh NaCl must be added through this inlet to keep the cell running.');

/* ---------- sodium riser, flask reservoir, outlet ---------- */
Ltube.path('M424,332 V300').fill('none').stroke({ color: C.ink, width: 18, linecap: 'butt' });
Ltube.path('M424,332 V300').fill('none').stroke({ color: C.pink, width: 12, linecap: 'butt' });
