Ltube.path('M420,296 H512').fill('none').stroke({ color: C.pink, width: 18 });

var spoutD = 'M529,314 V390 Q529,406 546,406 H584';
Ltube.path(spoutD).fill('none').stroke({ color: C.ink, width: 26, linejoin: 'round' });
Ltube.path(spoutD).fill('none').stroke({ color: C.pink, width: 19, linejoin: 'round' });

var bulbD = 'M506,302 V264 Q506,244 529,244 Q552,244 552,264 V302 L541,320 H517 Z';
Ltube.path(bulbD).fill('#ffffff').stroke({ color: C.ink, width: 3, linejoin: 'round' });
var naLevel = 292;
var naNeck = Ltube.polygon('507,302 551,302 540,319 518,319').fill(C.pink);
var naLiquid = Ltube.rect(44, 302 - naLevel).move(507, naLevel).fill(C.pink);
