hover(vbox, 'Voltage source — pushes electrons out of the anode into the cathode', 'The driving force',
  'Electrolysis is not spontaneous: the external supply pulls electrons from the anode (forcing oxidation of Cl⁻) and pushes them into the cathode (forcing reduction of Na⁺).');

/* ---------- labels ---------- */
halo(txt(Llab, 'Molten', 24, 266, 15));
halo(txt(Llab, 'NaCl', 24, 284, 15));
leader(Llab, 96, 292, 192, 292);
halo(txt(Llab, 'Iron', 48, 348, 15));
halo(txt(Llab, 'screen', 48, 366, 15));
leader(Llab, 116, 374, 246, 374);
halo(txt(Llab, 'Cathode (−)', 186, 508, 15));
leader(Llab, 240, 506, 220, 456);
halo(txt(Llab, 'Anode (+)', 344, 508, 15));
leader(Llab, 376, 506, 350, 396);
halo(txt(Llab, 'Cl₂ outlet', 500, 40, 15));
arrow(Llab, 497, 88, 596, 88, C.ink, 3, 14);
halo(txt(Llab, 'Inlet for', 634, 174, 15));
halo(txt(Llab, 'NaCl', 634, 192, 15));
leader(Llab, 448, 186, 628, 186);
halo(txt(Llab, 'Liquid', 570, 272, 15));
